#[doc = " The header and payload of the frame at the start of `bytes`, and the bytes after it."]
pub fn read_frame(bytes: &[u8]) -> ::core::result::Result<(Header, Vec<u8>, usize), DecodeError> {
    ::core::result::Result::Ok({
        let mut input = bytes;
        let header = Header::decode(&mut input)?;
        let len = header.len as usize;
        if input.len() < len + 2 {
            return Err(DecodeError::Short);
        };
        let payload = &input[..len];
        let found = u16::decode(&mut &input[len..])?;
        let expected = crc16(payload);
        if found != expected {
            return Err(DecodeError::BadCrc { expected, found });
        };
        (
            header,
            payload.to_vec(),
            bytes.len() - input.len() + len + 2,
        )
    })
}

